const upsertCommunicationPreferences = `-- name: UpsertCommunicationPreferences :one
INSERT INTO communication_preferences
    (user_id, security_email_enabled, general_email_enabled, push_enabled, updated_at)
VALUES ($1, $2, $3, $4, now())
ON CONFLICT (user_id) DO UPDATE
SET security_email_enabled = EXCLUDED.security_email_enabled,
    general_email_enabled = EXCLUDED.general_email_enabled,
    push_enabled = EXCLUDED.push_enabled, updated_at = now()
RETURNING user_id, security_email_enabled, general_email_enabled, push_enabled, updated_at
`

type UpsertCommunicationPreferencesParams struct {
	UserID               pgtype.UUID `json:"user_id"`
	SecurityEmailEnabled bool        `json:"security_email_enabled"`
	GeneralEmailEnabled  bool        `json:"general_email_enabled"`
	PushEnabled          bool        `json:"push_enabled"`
}

func (q *Queries) UpsertCommunicationPreferences(ctx context.Context, arg UpsertCommunicationPreferencesParams) (CommunicationPreference, error) {
	row := q.db.QueryRow(ctx, upsertCommunicationPreferences,
		arg.UserID,
		arg.SecurityEmailEnabled,
		arg.GeneralEmailEnabled,
		arg.PushEnabled,
	)
	var i CommunicationPreference
	err := row.Scan(
		&i.UserID,
		&i.SecurityEmailEnabled,
		&i.GeneralEmailEnabled,
		&i.PushEnabled,
		&i.UpdatedAt,
	)
	return i, err
}

const upsertDeviceRegistration = `-- name: UpsertDeviceRegistration :one

INSERT INTO device_registrations
    (id, user_id, provider, device_token, token_hash, enabled, last_seen_at,
     created_at, updated_at)
VALUES ($1, $2, $3, $4, $5, $6, now(), now(), now())
ON CONFLICT (user_id, provider, device_token) DO UPDATE
SET token_hash = EXCLUDED.token_hash, enabled = EXCLUDED.enabled,
    last_seen_at = now(), updated_at = now()
RETURNING id, user_id, provider, device_token, token_hash, enabled,
          last_seen_at, created_at, updated_at
`

type UpsertDeviceRegistrationParams struct {
	ID          pgtype.UUID `json:"id"`
	UserID      pgtype.UUID `json:"user_id"`
	Provider    string      `json:"provider"`
	DeviceToken string      `json:"device_token"`
	TokenHash   []byte      `json:"token_hash"`
	Enabled     bool        `json:"enabled"`
}

// Devices and communication preferences -----------------------------------
func (q *Queries) UpsertDeviceRegistration(ctx context.Context, arg UpsertDeviceRegistrationParams) (DeviceRegistration, error) {
	row := q.db.QueryRow(ctx, upsertDeviceRegistration,
		arg.ID,
		arg.UserID,
		arg.Provider,
		arg.DeviceToken,
		arg.TokenHash,
		arg.Enabled,
	)
	var i DeviceRegistration
	err := row.Scan(
		&i.ID,
		&i.UserID,
		&i.Provider,
		&i.DeviceToken,
		&i.TokenHash,
		&i.Enabled,
		&i.LastSeenAt,
		&i.CreatedAt,
		&i.UpdatedAt,
	)
	return i, err
}

const upsertRateLimitBucket = `-- name: UpsertRateLimitBucket :one
INSERT INTO rate_limit_buckets
    (scope, identifier_hmac, key_id, window_start, window_end, hit_count, updated_at)
VALUES ($1, $2, $3, $4, $5, $6, now())
ON CONFLICT (scope, identifier_hmac, window_start) DO UPDATE
SET hit_count = rate_limit_buckets.hit_count + EXCLUDED.hit_count,
    key_id = EXCLUDED.key_id, window_end = EXCLUDED.window_end, updated_at = now()
RETURNING scope, identifier_hmac, key_id, window_start, window_end, hit_count, updated_at
`

type UpsertRateLimitBucketParams struct {
	Scope          string             `json:"scope"`
	IdentifierHmac []byte             `json:"identifier_hmac"`
	KeyID          string             `json:"key_id"`
	WindowStart    pgtype.Timestamptz `json:"window_start"`
	WindowEnd      pgtype.Timestamptz `json:"window_end"`
	HitCount       int64              `json:"hit_count"`
}

func (q *Queries) UpsertRateLimitBucket(ctx context.Context, arg UpsertRateLimitBucketParams) (RateLimitBucket, error) {
	row := q.db.QueryRow(ctx, upsertRateLimitBucket,
		arg.Scope,
		arg.IdentifierHmac,
		arg.KeyID,
		arg.WindowStart,
		arg.WindowEnd,
		arg.HitCount,
	)
	var i RateLimitBucket
	err := row.Scan(
		&i.Scope,
		&i.IdentifierHmac,
		&i.KeyID,
		&i.WindowStart,
		&i.WindowEnd,
		&i.HitCount,
		&i.UpdatedAt,
	)
	return i, err
}
